import operator

def do_algebra(operator, operand):
    if len(operator) != len(operand) - 1:
        raise ValueError("The length of operator list should be equal to the length of operand list minus one.")

    if not set(operator) <= set(operators) or not all(isinstance(x, int) and x >= 0 for x in operand):
        raise ValueError("Operator list should contain only basic algebra operations and operand list should contain only non-negative integers.")

    if len(operator) == 1:
        return operand[0] * operand[1:]

    result = operand[0]
    for i in range(1, len(operand)):
        operation = operator[i - 1]
        if operation == '+':
            result += operand[i]
        elif operation == '-':
            result -= operand[i]
        elif operation == '*':
            result *= operand[i]
        elif operation == '//':
            result //= operand[i]
        elif operation == '**':
            result **= operand[i]

    return result

operators = {'+', '-', '*', '//', '**'}
